        # Define allowed operators and their precedence
        allowed_operators = {'+', '-', '*', '/'}
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

        # Split the expression into tokens (numbers and operators)
        tokens = expr.replace('(', ' ').replace(')', ' ').split()

        # Convert infix notation to postfix (Reverse Polish Notation)
        output_queue = []
        operator_stack = []

        for token in tokens:
            if token not in allowed_operators and not token.isdigit():
                return ""

