from asteval import Interpreter

def evaluate_expression(expr: str) -> str:
    try:
        aeval = Interpreter()
        # Allow basic arithmetic operations
        aeval.symtable.update({'__builtins__': None})
        result = aeval(expr)
        return str(result)
    except Exception:
        return ""
